    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 3);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from James Baldwin’s 1956 novel Giovanni’s Room. The narrator is riding in a taxi down a street lined with food vendors and shoppers in Paris, France."}, {"type": "paragraph", "text": "The multitude of Paris seems to be dressed in blue every day but Sunday, when, for the most part, they put on an unbelievably festive black. Here they were now, in blue, disputing, every inch, our passage, with their wagons, handtrucks, their bursting baskets carried at an angle steeply self-confident on the back."}, {"type": "paragraph", "text": "©1956 by James Baldwin"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Arguing about"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Disapproving of"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Asserting possession of"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Providing resistance to"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 4);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While recent scholarship has undermined claims that the works of twelfth-century Islamic philosopher Ibn Rushd were ______ other Muslim philosophers of his time, it is indisputable that his location in the Muslim-ruled area of what is now Spain meant that his works were primarily available thousands of miles west of the era’s center of Islamic thought."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "controversial among"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "antagonistic toward"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "imitated by"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "inconsequential to"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 5);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "On painter William H. Johnson’s return to the United States in 1938 after a decade in Europe, his style underwent an abrupt transformation. [[0|Turning away from landscapes painted in an expressionist style—a style that often involves using fluid, distorted shapes and thick, textured brushstrokes to express the artist’s subjective experience of reality—Johnson began painting portraits of Black Americans in a bold new way]]. Evocative of African sculpture and American and Scandinavian folk art, these portraits feature flat, deliberately oversimplified figures in a vibrant but limited color palette."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It elaborates on the previous sentence’s statement about a transitional moment in Johnson’s artistic career."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It provides information about Johnson’s travels in support of a claim about his artistic influences, which is advanced in the following sentence."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It recounts a moment in Johnson’s personal life that enabled the success of his subsequent career, which is summarized in the following sentence."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It presents evidence that calls into question the previous sentence’s characterization of Johnson’s artistic development."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 6);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "When classical pianist Martha Argerich performs, it appears as if the music is coming to her spontaneously. She’s highly skilled technically, but because of how freely she plays and her willingness to take risks, she seems relaxed and natural. Her apparent ease, however, is due to a tremendous amount of preparation. Despite Argerich’s experience and virtuosity, she never takes for granted that she knows a piece of music. Instead, she approaches the music as if encountering it for the first time and tries to understand it anew."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "To provide details about how Argerich identifies which pieces of music she will perform"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "To assert that Argerich’s performances look effortless because of how she prepares for them"}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "To discuss the kinds of music Argerich feels most comfortable encountering for the first time"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "To describe the unique way that Argerich approaches music she hasn’t performed before"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 7);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from Herman Melville’s 1855 novel Israel Potter. Israel is a young man wandering through New England during the late eighteenth century."}, {"type": "paragraph", "text": "He hired himself out for three months; at the end of that time to receive for his wages two hundred acres of land lying in New Hampshire. [...] His employer proving false to the contract in the matter of the land, and there being no law in the country to force him to fulfil it, Israel—who, [[0|however brave-hearted, and even much of a dare-devil upon a pinch, seems nevertheless to have evinced, throughout many parts of his career, a singular patience and]] mildness—was obliged to look round for other means of livelihood than clearing out a farm for himself in the wilderness."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It implies that Israel treasures a particular characteristic of his personality when that characteristic should usually be regarded as a flaw."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It suggests that if not for a certain aspect of his character, Israel might not have been as easily thwarted in his ambition to establish a farm."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It shows why Israel would not have been able to undertake the enormous amount of labor necessary to run a farm even if he had owned the necessary property."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It explains why, when the situation requires it, Israel is able to undertake courageous acts that others would generally avoid."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 8);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "heading", "text": "Text 1"}, {"type": "paragraph", "text": "In 1954 George Balanchine choreographed a production of The Nutcracker, a ballet by Pyotr Ilyich Tchaikovsky. It has since become a tradition for hundreds of dance companies in North America to stage The Nutcracker each year. [[0|But the show is stuck in the past, with an old-fashioned story and references, so it should no longer be produced]]. Ballet needs to create new traditions if it wants to stay relevant to contemporary audiences. Text 2 The Nutcracker is outdated, but it should be kept because it’s a holiday favorite and provides substantial income for some dance companies. Although it can be behind the times, there are creative ways to update the show. For example, Debbie Allen successfully modernized the story. Her show Hot Chocolate Nutcracker combines ballet, tap, hip-hop, and other styles, and it has been gaining in popularity since it opened in 2009."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "By questioning the idea that the story of The Nutcracker is stuck in the past and by rejecting the suggestion that contemporary audiences would enjoy an updated version"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "By agreeing that contemporary audiences have largely stopped going to see performances of The Nutcracker because it’s so old-fashioned"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "By pointing out that most dance companies could increase their incomes by offering modernized versions of The Nutcracker"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "By suggesting that dance companies should consider offering revised versions of The Nutcracker instead of completely rejecting the show"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 9);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "To understand how Paleolithic artists navigated dark Ma caves, archaeologist Ma Ángeles Medina-Alcaide and her team tested different lighting methods in a cave in Spain using replicas of artifacts found in European caves with art. They used three different Paleolithic light sources—torches, animal-fat lamps, and fireplaces—determining that each likely had a specific purpose. For instance, the team learned that the animal-fat lamps were less useful than torches while walking because the lamps didn’t illuminate the cave floor."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Medina-Alcaide and her team’s study demonstrated that fireplaces were essential to the creators of Paleolithic cave art."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Medina-Alcaide and her team discovered that Paleolithic cave artists in Spain used animal-fat lamps more often than they used torches."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Medina-Alcaide and her team were reluctant to draw many conclusions from their study because of the difficulty they had replicating light sources based on known artifacts."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Medina-Alcaide and her team tested Paleolithic light sources and learned some details about how Paleolithic artists traveled within dark caves."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 10);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-06/rw-m1-q11.png", "alt": "Table or graph for this question", "width": 356}, {"type": "paragraph", "text": "A student is using the table as part of a social studies class presentation on the US auto industry in the early twentieth century. The student notes that, according to the table, from 1910 to 1925 ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "the number of cars produced increased but the number of companies producing cars decreased."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "both the number of cars produced and the number of companies producing cars remained unchanged."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "the number of cars produced decreased but the number of companies producing cars remained unchanged."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "both the number of cars produced and the number of companies producing cars increased."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 11);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "External shopping cues are a type of marketing that uses obvious messaging—a display featuring a new product, for example, or a “buy one, get one free” offer—to entice consumers to make spontaneous purchases. In a study, data scientist Sam K. Hui and colleagues found that this effect can also be achieved with a less obvious cue: rearranging a store’s layout. The researchers explain that trying to find items in new locations causes shoppers to move through more of the store, exposing them to more products and increasing the likelihood that they’ll buy an item they hadn’t planned on purchasing."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "“I needed to buy some cleaning supplies, but they weren’t in their regular place. While I was looking for them, I saw this interesting notebook and decided to buy it, too.”"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "“I didn’t buy everything on my shopping list today. I couldn’t find a couple of the items in the store, even though I looked all over for them.”"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "“The store sent me a coupon for a new brand of soup, so I came here to find out what kinds of soup that brand offers. I decided to buy a few cans because I had the coupon.”"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "“This store is larger than one that’s closer to where I live, and it carries more products. I came here to buy some things that the other store doesn’t always have.”"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 12);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The 2021 exhibition This Is the Day at Arkansas’s Crystal Bridges Museum of American Art featured works dealing with expressions of faith and spirituality in the Black community. The museum’s 2022 exhibition The Dirty South, meanwhile, focused on Black culture in the American South from 1920 to 2020, with a particular focus on the intersections between visual arts and music. Together, these exhibitions don’t merely highlight the diversity of the Black experience in the US; [[0|they also showcase the diverse media through which artists have depicted and engaged with that experience]]."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Between them, This Is the Day and The Dirty South included drawings, paintings, photographs, sculptures, textiles, videos, costumes, and music."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "This Is the Day included works by fewer than two dozen artists, whereas The Dirty South included works by more than 80 artists."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "This Is the Day exclusively included works in the permanent collection of the museum, whereas The Dirty South included works from multiple sources outside the museum."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Between them, This Is the Day and The Dirty South included works depicting more than 300 years of Black experience in the United States."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 13);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-06/rw-m1-q14.png", "alt": "Table or graph for this question", "width": 298}, {"type": "paragraph", "text": "To investigate potential cognitive benefits of taking leave from work, psychologist Jan Packer and colleagues conducted a six-month study of Australian university staff members who took no leave from work during the study, took 2–4 days of leave, or took 1–5 weeks of leave. Tests of attentiveness were administered to participants three times during the study: at random for the no-leave staff, and for the rest, one week before their leave, one week following their return to work, and one week after the second test administration. After analyzing the results, the researchers concluded that longer leave times might not confer a greater cognitive benefit than shorter leave times do."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "In the second test administration, participants who took 2–4 days of leave had higher average attentiveness scores than did those who took no leave, but in the third test administration, those who took no leave had higher average scores than those who took 1–5 weeks of leave."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "In the first test administration, participants who took 2–4 days of leave had lower average attentiveness scores than did those who took 1–5 weeks of leave and those who took no leave."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "In both the second and third test administrations, participants who took 2–4 days of leave had higher average attentiveness scores than did participants who took 1–5 weeks of leave."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "In the second and third test administrations, participants who took 2–4 days of leave had higher average attentiveness scores than did those who took no leave."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 14);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-06/rw-m1-q15.png", "alt": "Table or graph for this question", "width": 296}, {"type": "paragraph", "text": "It may seem that the optimal strategy for an animal pursuing prey or escaping predators is to move at maximal speed, but the energy expense of exploiting full speed capacity can disfavor such a strategy even in escape contexts, as evidenced by the fact that ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "most lizard species use about the same percentage of their maximal speed when escaping predation as they do when pursuing prey."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "multiple lizard species move at an average of less than 90% of their maximal speed while escaping predation."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "more lizard species use, on average, 90%–100% of their maximal speed while escaping predation than use any other percentage of their maximal speed."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "at least 4 lizard species use, on average, less than 100% of their maximal speed while pursuing prey."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 15);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Under normal atmospheric pressure at Earth’s surface, water molecules form a tetrahedral network stabilized by hydrogen bonds between adjacent molecules. Extreme high pressure, such as can be found in deep ocean waters, destabilizes these bonds and compresses water’s structure, allowing water molecules within organisms to permeate proteins and impede crucial biological functions; yet deep-sea organisms known as piezophiles have adapted to extreme pressure. Studies have found a positive correlation between the depths that various piezophiles inhabit and concentrations of a compound called trimethylamine N-oxide (TMAO) in their muscle tissues, which has led a team of researchers to hypothesize that TMAO reduces water’s compressibility."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Water molecules are found to be impervious to TMAO even when the water molecules’ tetrahedral configuration has been distorted by high pressure."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Examination of TMAO’s molecular structure shows that TMAO molecules retain their shape even as pressure increases."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "A positive correlation is found between concentrations of TMAO and the rate at which water’s molecular structure compresses as pressure increases."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Analysis of water’s molecular structure under high pressure reveals that hydrogen bonds are more stable when TMAO is present than when it is not."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 16);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The Cretaceous pterosaur Tupandactylus navigans is known for having an anomalously oversized head crest. Until an almost complete fossil skeleton was found in Brazil, paleontologists had been able to study only skull specimens from T. navigans, though it was presumed that, like other pterosaurs, the species’s primary form of locomotion was powered flight. Examining the fuller skeleton in 2016, Victor Beccari and his team determined that T. navigans had long hind legs, short wings, and an unusually long neck—characteristics that, combined with the creature’s large-crested head, would have made sustained flight difficult and walking upright relatively comfortable. Based on these findings the team suggests that T. navigans likely ______"}]}'::jsonb, 'source') returning id into v_stim;
