    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In the 1930s, the Imperial Sugar Cane Institute in India sought to limit the country’s dependence on imported sugarcane.", "The institute enlisted botanist Janaki Ammal to breed a local variety of sugarcane.", "She crossbred the imported sugarcane species Saccharum officinarum with grasses native to India.", "She succeeded in creating sugarcane hybrids well suited to India’s climate."]}, {"type": "paragraph", "text": "The student wants to emphasize Janaki Ammal’s achievement."}]}'::jsonb, 'source') returning id into v_stim;
