    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Elizabeth Catlett’s sculpture Recognition (1970) shows two African American figures with rounded, indistinct features.", "The figures reach out to each other in a pose that symbolizes a close, supportive relationship.", "Her sculpture Students Aspire (1978) shows two African American figures with sharply defined features.", "The figures hold an equal sign above their heads with one hand and embrace each other with the other hand.", "This pose symbolizes their support for each other in the pursuit of equality."]}, {"type": "paragraph", "text": "The student wants to emphasize a similarity between the two sculptures."}]}'::jsonb, 'source') returning id into v_stim;
