    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The ancient Arab dhow was a sailing vessel distinguishable by its triangular sails and stitched hull construction.", "Dhows were used primarily for trade along the coasts of Arab, South Asian, and East African countries.", "Contemporary shipbuilders in Oman use a mix of modern and traditional materials to build replicas of ancient dhows.", "Most of the materials used are traditional.", "Replica hulls are stitched together using the same traditional coconut palm fiber rope used on the hulls of ancient dhows."]}, {"type": "paragraph", "text": "The student wants to make a generalization about the materials used in dhow replicas."}]}'::jsonb, 'source') returning id into v_stim;
