    values (v_subject, 'sat-practice-test-6-math', 'SAT Practice Test 6: Math', 'Official SAT Practice Test 6 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 213, '[[200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 210], [200, 210], [200, 230], [220, 260], [240, 320], [280, 340], [300, 340], [310, 350], [320, 360], [330, 370], [340, 380], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 500], [450, 510], [460, 520], [470, 530], [480, 540], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [570, 630], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 720], [680, 740], [700, 760], [720, 780], [750, 790], [760, 800], [780, 800], [790, 800], [790, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "(p + 3) + 8 = 10"}, {"type": "paragraph", "text": "What value of $p$ is the solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$p + 11 = 10$, so $p = -1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q02.png", "alt": "Figure for question 2", "width": 285}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables, $x$ and $y$."}, {"type": "paragraph", "text": "Which of the following graphs shows the most appropriate model for the data?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The data rise slowly at first and then more and more steeply, which is exponential growth. The curve in graph D passes through or close to every point; the curve in C sits well above the early points."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "k^2 - 53 = 91"}, {"type": "paragraph", "text": "What is the positive solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$k^2 = 144$, so the positive solution is $k = 12$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "During a portion of a flight, a small airplane''s cruising speed varied between $150$ miles per hour and $170$ miles per hour. Which inequality best represents this situation, where $s$ is the cruising speed, in miles per hour, during this portion of the flight?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The speed was never below $150$ or above $170$: $150 \\le s \\le 170$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q05.png", "alt": "Figure for question 5", "width": 291}, {"type": "paragraph", "text": "An object was launched upward from a platform. The graph shown models the height above ground, $y$, in meters, of the object $x$ seconds after it was launched. For which of the following intervals of time was the height of the object increasing for the entire interval?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graph rises from $x = 0$ to its peak at $x = 2$ and falls after that, so the height increases on the whole interval from $0$ to $2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "How many **yards** are equivalent to $1{,}116$ inches? ($1$ yard $= 36$ inches)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$1{,}116 \\div 36 = 31$ yards."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 6, 'spr', array['31']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 14 + 4x"}, {"type": "paragraph", "text": "The function $f$ represents the total cost, in dollars, of attending an arcade when $x$ games are played. How many games can be played for a total cost of $\\$58$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$14 + 4x = 58$, so $4x = 44$ and $x = 11$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['11']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = x + b"}, {"type": "paragraph", "text": "For the linear function $f$, $b$ is a constant. When $x = 0$, $f(x) = 30$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 0 + b = 30$, so $b = 30$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "P(t) = 1{,}800(1.02)^t"}, {"type": "paragraph", "text": "The function $P$ gives the estimated number of marine mammals in a certain area, where $t$ is the number of years since a study began. What is the best interpretation of $P(0) = 1{,}800$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$t = 0$ is when the study began, and $P(0) = 1{,}800$ is the estimated number of marine mammals at that time."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A manager is responsible for ordering supplies for a shaved ice shop. The shop''s inventory starts with $4{,}500$ paper cups, and the manager estimates that $70$ of these paper cups are used each day. Based on this estimate, in how many days will the supply of paper cups reach $1{,}700$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The shop must use $4{,}500 - 1{,}700 = 2{,}800$ cups, which takes $2{,}800 \\div 70 = 40$ days."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y > 4x + 8"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4x + 8$ equals $16$, $24$, and $32$ at $x = 2$, $4$, $6$. Only table A has every $y$ greater: $19 > 16$, $30 > 24$, $41 > 32$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(x^2 + 11)^2 + (x - 5)(x + 5)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$(x^2 + 11)^2 = x^4 + 22x^2 + 121$ and $(x - 5)(x + 5) = x^2 - 25$. The sum is $x^4 + 23x^2 + 96$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $h$ is defined by $h(x) = \\dfrac{8}{5x + 6}$. What is the value of $h(2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(2) = \\dfrac{8}{10 + 6} = \\dfrac{8}{16} = \\dfrac{1}{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 13, 'spr', array['.5', '1/2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q14.png", "alt": "Figure for question 14", "width": 261}, {"type": "paragraph", "text": "The figure shows the lengths, in inches, of two sides of a right triangle. What is the area of the triangle, in square inches?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The legs are $3$ and $5$, so the area is $\\tfrac{1}{2}(3)(5) = 7.5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 14, 'spr', array['7.5', '15/2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q15.png", "alt": "Figure for question 15", "width": 256}, {"type": "paragraph", "text": "The graph models the number of active projects a company was working on $x$ months after the end of November $2012$, where $0 \\le x \\le 6$. According to the model, what is the predicted number of active projects the company was working on at the end of November $2012$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The end of November $2012$ is $x = 0$, where the graph is at $y = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The relationship between two variables, $x$ and $y$, is linear. For every increase in the value of $x$ by $1$, the value of $y$ increases by $8$. When the value of $x$ is $2$, the value of $y$ is $18$. Which equation represents this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slope is $8$. Using $(2, 18)$: $18 = 8(2) + b$, so $b = 2$ and $y = 8x + 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "P = N(19 - C)"}, {"type": "paragraph", "text": "The given equation relates the positive numbers $P$, $N$, and $C$. Which equation correctly expresses $C$ in terms of $P$ and $N$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Divide by $N$: $\\dfrac{P}{N} = 19 - C$, so $C = 19 - \\dfrac{P}{N}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "w^2 + 12w - 40 = 0"}, {"type": "paragraph", "text": "Which of the following is a solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Complete the square: $(w + 6)^2 = 76$, so $w = -6 \\pm \\sqrt{76} = -6 \\pm 2\\sqrt{19}$. One solution is $-6 + 2\\sqrt{19}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q19.png", "alt": "Figure for question 19", "width": 302}, {"type": "paragraph", "text": "The table shown summarizes the number of employees at each of the $17$ restaurants in a town."}, {"type": "paragraph", "text": "Which of the following could be the median number of employees for the restaurants in this town?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "With $17$ values the median is the $9$th. The first three rows hold $2 + 4 + 2 = 8$ restaurants, so the $9$th is in the $20$ to $25$ group. Only $21$ is in that range."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the $y$-coordinate of the $y$-intercept of the graph of $\\dfrac{3x}{7} = -\\dfrac{5y}{9} + 21$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At the $y$-intercept $x = 0$: $\\dfrac{5y}{9} = 21$, so $y = \\dfrac{189}{5} = 37.8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 20, 'spr', array['189/5', '37.8']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q21.png", "alt": "Figure for question 21", "width": 258}, {"type": "paragraph", "text": "The graph of $y = 2x^2 + bx + c$ is shown, where $b$ and $c$ are constants. What is the value of $bc$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graph crosses the $y$-axis at $-6$, so $c = -6$. It passes through $(-2, -6)$ and $(0, -6)$, so the vertex is at $x = -1$: $-\\dfrac{b}{2(2)} = -1$ gives $b = 4$. Then $bc = -24$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['-24']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In $2008$, Zinah earned $14\\%$ more than in $2007$, and in $2009$ Zinah earned $4\\%$ more than in $2008$. If Zinah earned $y$ times as much in $2009$ as in $2007$, what is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Successive increases multiply: $1.14 \\times 1.04 = 1.1856$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q23.png", "alt": "Figure for question 23", "width": 177}, {"type": "paragraph", "text": "Circle $A$ (shown) is defined by the equation $(x + 2)^2 + y^2 = 9$. Circle $B$ (not shown) is the result of shifting circle $A$ down $6$ units and increasing the radius so that the radius of circle $B$ is $2$ times the radius of circle $A$. Which equation defines circle $B$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Circle $A$ has center $(-2, 0)$ and radius $3$. Circle $B$ has center $(-2, -6)$ and radius $6$, so $r^2 = 36 = (4)(9)$: $(x + 2)^2 + (y + 6)^2 = (4)(9)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q24.png", "alt": "Figure for question 24", "width": 261}, {"type": "paragraph", "text": "Right triangle $ABC$ is shown. What is the value of $\\tan A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $B$ is $30^\\circ$ and $C$ is $90^\\circ$, so $A = 60^\\circ$ and $\\tan 60^\\circ = \\sqrt{3}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "At the time that an article was first featured on the home page of a news website, there were $40$ comments on the article. An exponential model estimates that at the end of each hour after the article was first featured on the home page, the number of comments on the article had increased by $190\\%$ of the number of comments on the article at the end of the previous hour. Which of the following equations best represents this model, where $C$ is the estimated number of comments on the article $t$ hours after the article was first featured on the home page and $t \\le 4$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "An increase of $190\\%$ each hour multiplies the count by $1 + 1.90 = 2.9$: $C = 40(2.9)^t$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$g(x)$"], "rows": [["$-27$", "$3$"], ["$-9$", "$0$"], ["$21$", "$5$"]]}, {"type": "paragraph", "text": "The table shows three values of $x$ and their corresponding values of $g(x)$, where $g(x) = \\dfrac{f(x)}{x + 3}$ and $f$ is a linear function. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = (x + 3)g(x)$, so $f(-9) = (-6)(0) = 0$ and $f(-27) = (-24)(3) = -72$. The slope is $\\dfrac{0 - (-72)}{-9 - (-27)} = 4$, so $f(x) = 4(x + 9) = 4x + 36$ and the $y$-intercept is $(0, 36)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In right triangle $ABC$, angle $C$ is the right angle and $BC = 162$. Point $D$ on side $AB$ is connected by a line segment with point $E$ on side $AC$ such that line segment $DE$ is parallel to side $BC$ and $CE = 2AE$. What is the length of line segment $DE$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Triangles $ADE$ and $ABC$ are similar. Since $CE = 2AE$, $AE$ is one third of $AC$, so $DE$ is one third of $BC$: $\\tfrac{162}{3} = 54$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['54']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 8x$. For what value of $x$ does $f(x) = 72$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$8x = 72$, so $x = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q02.png", "alt": "Figure for question 2", "width": 200}, {"type": "paragraph", "text": "In the figure, two lines intersect at a point. Angle 1 and angle 2 are vertical angles. The measure of angle 1 is $72^\\circ$. What is the measure of angle 2?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Vertical angles are equal, so angle 2 also measures $72^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "On a street with $7$ houses, $2$ houses are blue. If a house from this street is selected at random, what is the probability of selecting a house that is blue?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$2$ of the $7$ houses are blue, so the probability is $\\tfrac{2}{7}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q04.png", "alt": "Figure for question 4", "width": 262}, {"type": "paragraph", "text": "The graph of function $f$ is shown, where $y = f(x)$."}, {"type": "paragraph", "text": "Which of the following describes function $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graph is a straight line that rises from left to right, so $f$ is increasing linear."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q05.png", "alt": "Figure for question 5", "width": 250}, {"type": "paragraph", "text": "The graph of the function $f$ is shown, where $y = f(x)$. What is the $y$-intercept of the graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line crosses the $y$-axis at $y = -4$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x &= 8 \\\\ x + 3y &= 26 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute $x = 8$: $3y = 18$, so $y = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['6']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The amount of Hanna''s bill for a food order was $\\$50$. Hanna gave a tip of $20\\%$ of the amount of the bill. What is the amount, in dollars, of the tip Hanna gave?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.20 \\times 50 = 10$ dollars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 7, 'spr', array['10']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $5x^5 - 6x^4 + 8x^3$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor out the greatest common factor $x^3$: $x^3(5x^2 - 6x + 8)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The ratio of the length of line segment $XY$ to the length of line segment $ZV$ is $6$ to $1$. If the length of line segment $XY$ is $102$ inches, what is the length, in inches, of line segment $ZV$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$ZV$ is one sixth of $XY$: $102 \\div 6 = 17$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "7(2x - 3) = 63"}, {"type": "paragraph", "text": "Which equation has the same solution as the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Dividing both sides by $7$ gives the equivalent equation $2x - 3 = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ defined by $f(t) = 14t + 9$ gives the estimated length, in inches, of a vine plant $t$ months after Tavon purchased it. Which of the following is the best interpretation of $9$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 9$: at $t = 0$, the purchase date, the plant''s estimated length was $9$ inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "(x + 2)(x - 5)(x + 9) = 0"}, {"type": "paragraph", "text": "What is a positive solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The solutions are $-2$, $5$, and $-9$. The positive one is $5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Brian saves $\\dfrac{2}{5}$ of the $\\$215$ he earns each week from his job. If Brian continues to save at this rate, how much money, in dollars, will Brian save in $9$ weeks?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each week he saves $\\tfrac{2}{5}(215) = 86$ dollars, so in $9$ weeks he saves $9 \\times 86 = 774$ dollars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 13, 'spr', array['774']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A rectangle has an area of $155$ square inches. The length of the rectangle is $4$ inches less than $7$ times the width of the rectangle. What is the width of the rectangle, in inches?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "With width $w$: $w(7w - 4) = 155$, so $7w^2 - 4w - 155 = 0$, which factors as $(7w + 31)(w - 5) = 0$. The width is $5$ inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "4, 10, 18, 4, 4, 5, 6, 5"}, {"type": "paragraph", "text": "What is the median of the data set shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In order: $4, 4, 4, 5, 5, 6, 10, 18$. With $8$ values the median is the average of the $4$th and $5$th: $\\tfrac{5 + 5}{2} = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right circular cylinder has a volume of $432$ cubic centimeters. The area of the base of the cylinder is $24$ square centimeters. What is the height, in centimeters, of the cylinder?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Volume $=$ base area $\\times$ height, so $h = \\tfrac{432}{24} = 18$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x^2 = -841"}, {"type": "paragraph", "text": "How many distinct real solutions does the given equation have?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A real number squared is never negative, so there are no real solutions."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Line $k$ is defined by $y = 7x + \\dfrac{1}{8}$. Line $j$ is perpendicular to line $k$ in the $xy$-plane. What is the slope of line $j$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Perpendicular slopes are negative reciprocals. Line $k$ has slope $7$, so line $j$ has slope $-\\tfrac{1}{7}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["Number of cars", "Maximum number of passengers and crew"], "rows": [["$3$", "$174$"], ["$5$", "$284$"], ["$10$", "$559$"]]}, {"type": "paragraph", "text": "The table shows the linear relationship between the number of cars, $c$, on a commuter train and the maximum number of passengers and crew, $p$, that the train can carry. Which equation represents the linear relationship between $c$ and $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slope is $\\tfrac{284 - 174}{5 - 3} = 55$, and $174 = 55(3) + 9$, so $p = 55c + 9$, which rearranges to $55c - p = -9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $4^{8c} = \\sqrt[3]{4^7}$, what is the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt[3]{4^7} = 4^{7/3}$, so $8c = \\tfrac{7}{3}$ and $c = \\tfrac{7}{24}$ (about $0.2917$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 20, 'spr', array['.2916', '.2917', '7/24']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} (x - 2) - 4(y + 7) &= 117 \\\\ (x - 2) + 4(y + 7) &= 442 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $6(x - 2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the equations: $2(x - 2) = 559$. Multiply by $3$: $6(x - 2) = 1{,}677$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 21, 'spr', array['1677']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $ABC$, angle $B$ is a right angle. The length of side $AB$ is $10\\sqrt{37}$ and the length of side $BC$ is $24\\sqrt{37}$. What is the length of side $AC$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$AC$ is the hypotenuse: $AC^2 = 100(37) + 576(37) = 676(37)$, so $AC = 26\\sqrt{37}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = (1.84)^{\\frac{x}{4}}"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. The equation can be rewritten as $f(x) = \\left(1 + \\dfrac{p}{100}\\right)^x$, where $p$ is a constant. Which of the following is closest to the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$(1.84)^{x/4} = \\left(1.84^{1/4}\\right)^x \\approx 1.165^x$, so $\\tfrac{p}{100} \\approx 0.165$ and $p$ is closest to $16$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = a\\sqrt{x + b}$, where $a$ and $b$ are constants. In the $xy$-plane, the graph of $y = f(x)$ passes through the point $(-24, 0)$, and $f(24) < 0$. Which of the following must be true?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(-24) = a\\sqrt{b - 24} = 0$ gives $b = 24$. Then $f(24) = a\\sqrt{48} < 0$ means $a < 0$, so $a < b$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In the $xy$-plane, a circle has center $C$ with coordinates $(h, k)$. Points $A$ and $B$ lie on the circle. Point $A$ has coordinates $\\left(h + 1, k + \\sqrt{102}\\right)$, and $\\angle ACB$ is a right angle. What is the length of $\\overline{AB}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The radius is $CA = \\sqrt{1 + 102} = \\sqrt{103}$. Triangle $ACB$ is an isosceles right triangle with legs $\\sqrt{103}$, so $AB = \\sqrt{103}\\cdot\\sqrt{2} = \\sqrt{206}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q26.png", "alt": "Figure for question 26", "width": 256}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables, $x$ and $y$, for data set E. A line of best fit is shown. Data set F is created by multiplying the $y$-coordinate of each data point from data set E by $3.9$. Which of the following could be an equation of a line of best fit for data set F?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line for E is about $y = 12 + 1.5x$. Multiplying every $y$-value by $3.9$ multiplies the intercept and slope by $3.9$: about $y = 46.8 + 5.85x$, closest to $y = 46.8 + 5.9x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 48x - 64y &= 48y + 24 \\\\ ry &= \\frac{1}{8} - 12x \\end{aligned}"}, {"type": "paragraph", "text": "In the given system of equations, $r$ is a constant. If the system has no solution, what is the value of $r$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Rewrite: $48x - 112y = 24$ and $12x + ry = \\tfrac{1}{8}$. Multiplying the second by $4$ gives $48x + 4ry = \\tfrac{1}{2}$. No solution means parallel lines with different constants, so $4r = -112$ and $r = -28$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 27, 'spr', array['-28']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;
